insert into meta (key, value) values ('updated', '"2026-10-16"');
insert into meta (key, value) values ('rule', '"Every posting names physics or natural sciences as an accepted degree, accepts a Bachelor, is not student or PhD, and links to the employer''s own page."');
insert into meta (key, value) values ('rule_eu', '"Europe outside Germany. Every posting names physics or natural sciences as an accepted degree and is at an employer that hires internationals."');
insert into meta (key, value) values ('target_per_area', '3');
insert into meta (key, value) values ('log_updated', '"2026-10-12"');
insert into meta (key, value) values ('rule_de', '"Jede Stelle nennt Physik oder Naturwissenschaften als zugelassenen Abschluss, akzeptiert einen Bachelor, richtet sich nicht an Studierende oder Promovierende und verlinkt auf die Seite des Arbeitgebers selbst. In der Produktionsleitung zählen geforderte Berufs- und Führungserfahrung nicht, denn diese Erfahrung ist vorhanden; in allen anderen Bereichen bleiben Stellen nur für Erfahrene außen vor. KI-Training heißt: KI an Aufgaben aus Physik und Mathematik trainieren oder ihre Lösungen bewerten. Content-Erstellung schließt Schulunterricht aus. Prüf- und Messtechnik umfasst Stellen, deren eigentliches Ergebnis eine Messung, ein Prüfergebnis, eine Kalibrierung oder die Qualifizierung eines Geräts ist, oder der Prüfstand, der dies liefert."');
insert into meta (key, value) values ('rule_eu_de', '"Europa ohne Deutschland. Jede Stelle nennt Physik oder Naturwissenschaften als zugelassenen Abschluss, akzeptiert einen Bachelor, richtet sich nicht an Studierende oder Promovierende, verlinkt auf die Seite des Arbeitgebers und stammt von einem Arbeitgeber, der international einstellt: Die Anzeige bietet Unterstützung bei Visum, Arbeitserlaubnis oder Umzug, oder der Arbeitgeber steht im amtlichen Register des Landes (Niederlande: IND, Vereinigtes Königreich: Home Office, Dänemark: SIRI, Irland: Liste der Arbeitserlaubnisse). Arbeitssprache ist Englisch oder Deutsch, oder die Landessprache wird im Arbeitsalltag nicht verlangt. In der Produktionsleitung zählen geforderte Berufs- und Führungserfahrung nicht; in allen anderen Bereichen bleiben Stellen nur für Erfahrene außen vor."');
